// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/domain/capability.ts`. Edit the source and run `just generate`.
// The merge of the requirements of a change into a main spec at `archive`.
// Plain data and pure functions only.

import { requirementsOf } from "./requirements.ts";

/** The lines after the first `# ` heading of a requirements file, with no blank line at the ends. */
export const afterTitle = (text: string): string => {
  const lines = text.split("\n");
  const title = lines.findIndex((l) => l.startsWith("# "));
  return lines
    .slice(title + 1)
    .join("\n")
    .trim();
};

/** The `## Requirements` section of a trivial `change.md`, with no heading and no blank line at the ends. Gives the empty string when there is none. */
export const requirementsSection = (text: string): string => {
  const lines = text.split("\n");
  const start = lines.findIndex((l) => l.trim() === "## Requirements");
  if (start < 0) return "";
  const end = lines.findIndex((l, i) => i > start && /^## /.test(l));
  return lines
    .slice(start + 1, end < 0 ? undefined : end)
    .join("\n")
    .trim();
};

/**
 * The text of `specs/<capability>.md` after the merge of `body`, the requirement sections of a change.
 * `previous` is the current text of the spec, or null for a new spec, and `fresh` is the text to start from when there is none.
 * It gives the errors when a requirement of `body` has an ID that `previous` has already.
 */
export const mergeRequirements = (
  previous: string | null,
  fresh: string,
  body: string,
): { text: string } | { errors: string[] } => {
  const base = previous ?? fresh;
  const known = new Set(requirementsOf(base).requirements.map((r) => r.id));
  const clash = requirementsOf(body).requirements.filter((r) =>
    known.has(r.id),
  );
  if (clash.length > 0)
    return {
      errors: clash.map((r) => `\`REQ-${r.id}\` is in the spec already`),
    };
  return { text: `${base.trimEnd()}\n\n${body}\n` };
};
